Registras seis middlewares de un hook cada uno, en este orden:

```python
from langchain.agents import create_agent
from langchain.agents.middleware import before_model, after_model, wrap_model_call


@before_model
def a_before(state, runtime):
    print("A.before_model")


@before_model
def b_before(state, runtime):
    print("B.before_model")


@after_model
def a_after(state, runtime):
    print("A.after_model")


@after_model
def b_after(state, runtime):
    print("B.after_model")


@wrap_model_call
def a_wrap(request, handler):
    print("A.wrap entra")
    response = handler(request)
    print("A.wrap sale")
    return response


@wrap_model_call
def b_wrap(request, handler):
    print("B.wrap entra")
    response = handler(request)
    print("B.wrap sale")
    return response


agent = create_agent(
    model="gpt-5-nano",
    middleware=[a_before, b_before, a_after, b_after, a_wrap, b_wrap],
)
agent.invoke({"messages": [{"role": "user", "content": "hi"}]})
```

